// <auto-generated-like />
// Thin, modern .NET 10+ interop layer for the unified CNET native library.
// Uses LibraryImport for source generation, AOT-friendliness, and performance.
// Target: .NET 10 (or .NET 8/9 with LibraryImport available).
//
// Build the C library first:
//   make cnet_dll
// Then ensure cnet.dll (or cnet.so) is next to your app or in PATH / LD_LIBRARY_PATH.

using System;
