    // Unified superset library: CCE + certified CNET engine + soul host.
    // The compatibility cce library may still be built for native consumers,
    // but managed code has one source of native ABI truth.
    private const string LibraryName = "cnet";
    private const string CnetLibraryName = LibraryName;

    static CceNative()
    {
        // Improve P/Invoke reliability: try to load from locations next to this assembly,
        // the current directory, or the app context base directory.
        TryRegisterNativeLibraryResolver();
    }

    private static void TryRegisterNativeLibraryResolver()
    {
        try
        {
            string baseDir = System.AppContext.BaseDirectory;
            string currentDir = Environment.CurrentDirectory;

            // Common locations during development and after `dotnet build/test`
            string[] candidateDirs = {
                baseDir,
                currentDir,
                System.IO.Path.GetFullPath(System.IO.Path.Combine(baseDir, "..")),
                System.IO.Path.GetFullPath(System.IO.Path.Combine(currentDir, "..", "..", "..")),
            };

            foreach (string dir in candidateDirs.Distinct(StringComparer.OrdinalIgnoreCase))
            {
                if (string.IsNullOrEmpty(dir)) continue;

                // Unified CNET engine (CCE + soul_host + route/dag).
                string cnetDll = System.IO.Path.Combine(dir, "cnet.dll");
                string cnetSo = System.IO.Path.Combine(dir, "cnet.so");
                string cnetDylib = System.IO.Path.Combine(dir, "cnet.dylib");
                if (System.IO.File.Exists(cnetDll)) { System.Runtime.InteropServices.NativeLibrary.Load(cnetDll); return; }
                if (System.IO.File.Exists(cnetSo)) { System.Runtime.InteropServices.NativeLibrary.Load(cnetSo); return; }
                if (System.IO.File.Exists(cnetDylib)) { System.Runtime.InteropServices.NativeLibrary.Load(cnetDylib); return; }
            }

            // Last attempt: explicit load using full known location from repo root relative to current dir
            var possibleRootDll = System.IO.Path.GetFullPath(System.IO.Path.Combine(currentDir, "..", "..", "..", "cnet.dll"));
            if (System.IO.File.Exists(possibleRootDll))
            {
                System.Runtime.InteropServices.NativeLibrary.Load(possibleRootDll);
            }
        }
        catch
        {
            // Let the normal P/Invoke search continue
        }
    }

